/**
 * Loads the wasm-bindgen build of `crates/query-analyzer` (ADR-002).
 * Generated by `pnpm build:wasm` into `src/generated/query-analyzer/`.
 */

import type { PlanDiff, QueryPlan, RawPlanRow } from "../../shared/contracts";
import init, {
  diffPlans as diffPlansRaw,
  parsePlan as parsePlanRaw,
  toolkitVersion as toolkitVersionRaw,
} from "../../generated/query-analyzer/query_analyzer";
import type { PlanToolkit } from "./planToolkit";

export async function loadRustToolkit(): Promise<PlanToolkit> {
  await init();
  return {
    parsePlan: (rows: RawPlanRow[], sqliteVersion: string): QueryPlan =>
      parsePlanRaw(rows, sqliteVersion) as QueryPlan,
    diffPlans: (before: QueryPlan, after: QueryPlan): PlanDiff =>
      diffPlansRaw(before, after) as PlanDiff,
  };
}

export function rustToolkitVersion(): string {
  return toolkitVersionRaw();
}
